/**
 * Light and dark mode.
 *
 * The page's <head> sets data-theme on <html> before anything is drawn (a
 * short inline script — so there is no white flash). This module takes over
 * from there: every [data-theme-toggle] button on the page switches the theme,
 * the choice is remembered on this device, and until someone chooses, the app
 * follows the phone's own light/dark setting. The colours are in css/dark.css,
 * generated by scripts/make-dark-css.mjs.
 */
const KEY = 'qht_theme';

const saved = () => {
  try { const t = localStorage.getItem(KEY); return t === 'dark' || t === 'light' ? t : null; } catch { return null; }
};
const systemTheme = () => (matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light');

export const currentTheme = () => (document.documentElement.dataset.theme === 'dark' ? 'dark' : 'light');

/** The switch, as markup — the moon shows in light mode, the sun in dark. */
export const THEME_BUTTON = (cls = '') => `
  <button type="button" class="theme-btn ${cls}" data-theme-toggle
          aria-label="Switch between light and dark mode" title="Light / dark mode">
    <svg class="i-moon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"
         stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M21 12.8A9 9 0 1 1 11.2 3a7 7 0 0 0 9.8 9.8z"/></svg>
    <svg class="i-sun" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"
         stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M4.9 4.9l1.4 1.4M17.7 17.7l1.4 1.4M2 12h2M20 12h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/></svg>
  </button>`;

export function applyTheme(theme) {
  const dark = theme === 'dark';
  document.documentElement.dataset.theme = dark ? 'dark' : 'light';
  document.querySelectorAll('[data-theme-toggle]').forEach(b => b.setAttribute('aria-pressed', String(dark)));

  // the browser's own bar matches the app's top bar
  const bar = document.querySelector('.topbar');
  const colour = bar ? getComputedStyle(bar).backgroundColor : getComputedStyle(document.body || document.documentElement).backgroundColor;
  document.querySelector('meta[name="theme-color"]')?.setAttribute('content', colour);

  // Android app: light status-bar icons on the dark theme, dark icons on the light one
  window.Capacitor?.Plugins?.SystemBars?.setStyle?.({ style: dark ? 'DARK' : 'LIGHT' })?.catch?.(() => {});
}

export function setTheme(theme) {
  try { localStorage.setItem(KEY, theme); } catch { /* private mode: still switches for now */ }
  applyTheme(theme);
}

export const toggleTheme = () => setTheme(currentTheme() === 'dark' ? 'light' : 'dark');

/* One listener for every switch, including ones drawn later. */
document.addEventListener('click', e => {
  if (e.target.closest?.('[data-theme-toggle]')) toggleTheme();
});

/* No choice made yet: follow the phone when it changes. */
matchMedia('(prefers-color-scheme: dark)').addEventListener?.('change', () => {
  if (!saved()) applyTheme(systemTheme());
});

applyTheme(saved() || systemTheme());
